html body.cre-t-276-modal-open main.main,
html body.cre-t-276-modal-open header.site-header,
html body.cre-t-276-modal-open .desktop-promo-container {
    filter: blur(5px);
}

html body .cre-t-276-modal-overlay {
    position: fixed;
    top: 0 !important;
    left: 0;
    width: 100%;
    height: 100%;
    /* background-color: rgb(0 0 0 / 60%); */
    background: rgba(133, 130, 130, 0.6);
    z-index: 2147483649 !important;
}

html body .cre-t-276-modal-container {
    position: fixed;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
    padding: 0;
    z-index: 2147483650 !important;
    text-align: center;
    max-width: 674px;
    width: calc(100% - 30px);
    overflow: hidden;
    transition: transform 0.6s cubic-bezier(0.165, 0.84, 0.44, 1);
}

html body.cre-t-276-modal-open .cre-t-276-modal-overlay {
    display: block !important;
}

html body.cre-t-276-modal-open .cre-t-276-modal-container {
    display: block !important;
}

html body .cre-t-276-modal-wrapper {
    display: flex;
    align-items: center;
    justify-content: center;
    flex-direction: column;
    padding: 72px 25px 82px;
    position: relative;
    border-radius: 12px;
    background: linear-gradient(180deg, #e8f1f5 0%, #eef5f7 50%, #f3f7f8 100%);
    box-shadow:
        0 20px 24px -4px rgba(16, 24, 40, 0.08),
        0 8px 8px -4px rgba(16, 24, 40, 0.03);
}

html body .cre-t-276-modal-close {
    width: 25px;
    height: 25px;
    min-width: 25px;
    display: flex;
    align-items: center;
    justify-content: center;
    position: absolute;
    right: 25px;
    top: 24px;
    cursor: pointer;
}

html body .cre-t-276-content {
    display: flex;
    align-items: center;
    justify-content: center;
    flex-direction: column;
    max-width: 500px;
    width: 100%;
}

html body .cre-t-276-content-wrap {
    display: flex;
    align-items: center;
    justify-content: center;
    flex-direction: column;
    width: 100%;
}

html body .cre-t-276-eyebrow {
    color: #000;
    text-align: center;
    font-family: inherit;
    font-size: 18px;
    font-style: normal;
    font-weight: 700;
    line-height: 37px;
}

html body .cre-t-276-title {
    color: #000;
    text-align: center;
    font-family: inherit;
    font-size: 31px;
    font-style: normal;
    font-weight: 700;
    line-height: 40px;
    margin-bottom: 19px;
    max-width: 450px;
}

html body .cre-t-276-description {
    color: #000;
    text-align: center;
    font-family: inherit;
    font-size: 15px;
    font-style: normal;
    font-weight: 400;
    line-height: 24px;
    margin-bottom: 23px;
    max-width: 450px;
}

html body .cre-t-276-description__bold {
    font-weight: 700;
}

html body .cre-t-276-price-line {
    color: #000;
    font-family: inherit;
    font-size: 19px;
    font-style: normal;
    font-weight: 700;
    line-height: 24px;
    margin-bottom: 35px;
}

html body .cre-t-276-price-line__strike {
    text-decoration-line: line-through;
}

html body .cre-t-276-cta {
    position: relative;
    overflow: hidden;
    display: flex;
    width: 100%;
    min-height: 61px;
    padding: 17px 25px;
    justify-content: center;
    align-items: center;
    gap: 7px;
    border-radius: 8px;
    background: #fe5f4c;
    cursor: pointer;
    transition:
        background 0.6s cubic-bezier(0.165, 0.84, 0.44, 1),
        color 0.6s cubic-bezier(0.165, 0.84, 0.44, 1);
}

html body .cre-t-276-cta-text {
    color: #fff;
    text-align: center;
    font-family: inherit;
    font-size: 15px;
    font-style: normal;
    font-weight: 700;
    line-height: normal;
    letter-spacing: 0.6px;
    transition:
        background 0.6s cubic-bezier(0.165, 0.84, 0.44, 1),
        color 0.6s cubic-bezier(0.165, 0.84, 0.44, 1);
}

html body .cre-t-276-cta:hover {
    background: #ce4b3c;
    color: #fff;
}

html body .cre-t-276-cta:hover .cre-t-276-cta-text {
    color: #fff;
}

html body .cre-t-276-snow-bg {
    position: absolute;
    display: flex;
    align-items: center;
    justify-content: center;
    pointer-events: none;
}

html body .cre-t-276-snow-bg.cre-t-276-snow-top-left {
    left: 10px;
    top: 67px;
    width: 28px;
    min-width: 28px;
    height: 30px;
}

html body .cre-t-276-snow-bg.cre-t-276-snow-top-large {
    left: 45px;
    top: 0;
}

html body .cre-t-276-snow-bg.cre-t-276-snow-top-right {
    left: 140px;
    top: 13px;
    width: 45px;
    min-width: 45px;
    height: 48px;
}

html body .cre-t-276-snow-bg.cre-t-276-snow-bottom-large {
    right: 37px;
    bottom: 0;
}

html body .cre-t-276-snow-bg.cre-t-276-snow-bottom-right {
    right: 11px;
    bottom: 48px;
    width: 28px;
    min-width: 28px;
    height: 30px;
}

html body .cre-t-276-snow-bg img {
    width: 100%;
    height: 100%;
    -o-object-fit: contain;
    object-fit: contain;
}

@media (max-width: 767px) {
